(()=>{'use strict';
const C=window.PracticalCore,D=C.D,e=C.esc,app=document.querySelector('#app'),dialog=document.querySelector('#resource-dialog');
const teacher=new URLSearchParams(location.search).get('teacher')==='1';
let s=C.initial(),storageOK=true,reportMode=false,focusReturn=null,toastTimer;
try{const raw=localStorage.getItem(C.KEY);if(raw)s=C.restore(JSON.parse(raw));}catch(_){storageOK=false;}
function t(en,zh=''){return `<span class="i18n">${e(en)}${s.lang==='bi'&&zh?`<span class="zh" lang="zh-Hans">${e(zh)}</span>`:''}</span>`;}
const p=v=>t(v.en,v.zh);
function save(){s.updated=new Date().toISOString();try{localStorage.setItem(C.KEY,JSON.stringify(s));}catch(_){storageOK=false;}}
function toast(en,zh){const a=document.querySelector('#toast');a.innerHTML=t(en,zh);a.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>a.hidden=true,3400);}
const active=()=>D.pages.find(x=>x.id===s.slide)||D.pages[0];
function ext(url,label,cls='button'){return `<a class="${cls}" href="${e(url)}" target="_blank" rel="noopener noreferrer">${label}<span aria-hidden="true"> ↗</span></a>`;}
function captionText(caption){const i=caption.search(/[\u3400-\u9fff]/);return i<0?e(caption):t(caption.slice(0,i).replace(/[ /]+$/,'').trim(),caption.slice(i));}
function figure(id,caption='',full=false){return `<figure class="guide-figure"><button class="figure-zoom" data-guide="${e(id)}" aria-label="${e(s.lang==='bi'?'放大步骤截图':'Enlarge the step screenshot')}"><img src="assets/${full?'guides/'+id+'.png':'steps/'+id+'.webp'}" alt="${e(caption||'Annotated MIT screenshot for this step')}" loading="eager"><span class="zoom-label">${t('Enlarge guide','放大指南')} ⤢</span></button>${caption?`<figcaption>${captionText(caption)}</figcaption>`:''}</figure>`;}
function helpButton(id,label){return `<button class="button subtle small" data-help="${e(id)}">${label||t('Help with this step','这一步的帮助')}</button>`;}
function inputWord(key,label,placeholder='',hint=''){return `<label class="field"><span>${label}</span>${key==='response'||key==='intro'?`<textarea data-word="${key}" rows="2" maxlength="${key==='response'?240:120}" placeholder="${e(placeholder)}">${e(s.words[key])}</textarea>`:`<input data-word="${key}" maxlength="120" value="${e(s.words[key])}" placeholder="${e(placeholder)}">`}${hint?`<small>${hint}</small>`:''}</label>`;}
function storageBanner(){return storageOK?'':`<div class="notice warning">${t('This browser is not saving progress. Download a backup before closing.','当前浏览器未能保存进度，请在关闭前下载备份。')} <button data-action="backup" class="text-button">${t('Download backup','下载备份')}</button></div>`;}
function header(){return `<header class="topbar"><button class="brand" data-action="home"><span class="brand-mark">M<span>✦</span></span><span>CS with Mr Dave<small>YEAR 9 · APP STUDIO</small></span></button><div class="top-actions">${teacher?'<span class="teacher-pill">Teacher view</span>':''}<label class="sr-only" for="language">Language</label><select id="language" aria-label="Language"><option value="en" ${s.lang==='en'?'selected':''}>English</option><option value="bi" ${s.lang==='bi'?'selected':''}>English + 中文</option></select><button class="button small ${s.guided?'selected':''}" data-action="guided" aria-pressed="${s.guided}">${t('Extra guidance','更多引导')}</button><button class="button subtle small" data-action="resources">${t('Resources','资源')}</button></div></header>`;}
function landing(){document.title='Make It Yours · Year 9 App Studio';return `${header()}${storageBanner()}<main id="main" class="landing"><section class="landing-copy"><span class="eyebrow">${t('YOUR IDEA. YOUR FIRST WORKING APP.','你的创意，你的第一个能运行的应用。')}</span><h1>${t('Make it yours.','做出你的风格。')}</h1><p class="lead">${t('Bring a homepage sketch, or start with something you enjoy. Make it real in MIT App Inventor.','带上你的首页草图，或从自己感兴趣的主题开始，在 MIT App Inventor 中做出来。')}</p><div class="outcome-strip"><span><b>01</b>${t('Personalise a homepage','制作自己的首页')}</span><span><b>02</b>${t('Make a button respond','让按钮作出响应')}</span></div><div class="landing-form card"><label class="field">${t('Your name','你的名字')}<input id="student-name" maxlength="90" autocomplete="name" value="${e(s.student.name)}" placeholder="${e(s.lang==='bi'?'输入名字':'First and last name')}"></label><label class="field short">${t('Class','班级')}<input id="student-form" maxlength="35" value="${e(s.student.form)}" placeholder="9E / 9T"></label><button class="button primary start" data-action="join">${s.visited.length?t('Continue my app','继续我的应用'):t('Enter the studio','进入创作室')} <span aria-hidden="true">→</span></button></div><p class="quiet-caption">${t('60 minutes · Two Main Tasks · No theory sketch? There is a quick-start route.','60 分钟 · 两个主要任务 · 没有理论课草图？有简短起步路线。')}</p>${s.visited.length?`<button class="text-button" data-action="new-record">${t('Start a new learner record','开始新同学的记录')}</button>`:''}<p class="privacy-note">${t('This lesson keeps your notes on this browser. Your app is built and saved in MIT.','本课笔记保存在这个浏览器中；真正的应用在 MIT 中制作和保存。')}</p></section><section class="landing-art" aria-label="App ideas"><div class="art-orbit" aria-hidden="true"></div><div class="phone hero-phone"><div class="phone-screen"><small>YOUR APP / 你的应用</small><h2>${t('Something you love.','从你喜欢的开始。')}</h2><img src="assets/art/gaming.svg" alt="Illustration of a game controller"><div class="phone-button">${t('Show me more','了解更多')}</div><p>${t('A homepage. A tap. A response.','一个首页，一次点击，一个响应。')}</p></div></div><div class="floating-art fashion"><img src="assets/art/fashion.svg" alt="Fashion idea"></div><div class="floating-art camera"><img src="assets/art/camera.svg" alt="Photography idea"></div><div class="hero-note">${t('Choose your topic. Keep your voice.','自己选主题，表达自己的想法。')}</div></section></main>`;}
function rail(){const pg=active();return `<aside class="rail"><button class="mobile-purpose-toggle" data-action="toggle-purpose" aria-expanded="false">${t('Today’s WAGBA, KSU & lesson steps','今天的目标、知识技能理解与步骤')} <span aria-hidden="true">+</span></button><div class="rail-body"><div class="rail-heading">${t('TODAY’S PURPOSE','今天的目标')}</div><div class="rail-goal"><strong>WAGBA</strong><p>${p(D.wagba)}</p></div><div class="ksu-list">${['K','S','U'].map(a=>`<details open><summary><b>${a}</b>${p(D.areas[a])}</summary><p>${p(D.targets[a])}</p></details>`).join('')}</div><nav aria-label="Lesson stages">${D.groups.map((g,i)=>{const start=D.pages.find(x=>x.group===g.id),unlocked=C.canVisit(s,start.id,teacher),is=g.id===pg.group;return `<button class="stage-link ${is?'active':''}" data-go="${start.id}" ${!unlocked?'disabled':''} ${is?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span><span>${p(g)}</span>${!unlocked?'<span class="lock" aria-hidden="true">·</span>':''}</button>`;}).join('')}</nav><p class="rail-status">${t(storageOK?'Saved on this browser':'Use a backup to keep progress',storageOK?'进度保存在此浏览器':'请用备份保留进度')}</p></div></aside>`;}
function frame(){const pg=active(),group=D.groups.find(g=>g.id===pg.group),inGroup=C.path(s).filter(p=>p.group===pg.group),i=inGroup.findIndex(p=>p.id===pg.id);document.title=pg.title.en+' · My First MIT App';return `${header()}${storageBanner()}<div class="layout">${rail()}<main id="main" class="main" tabindex="-1"><div class="slide-top"><span>${p(group)}</span><span>${t('Step '+(i+1)+' of '+inGroup.length,'第 '+(i+1)+' 步，共 '+inGroup.length+' 步')}</span></div><div class="step-track" aria-label="${e(group.en+' steps')}">${inGroup.map(x=>`<button data-go="${x.id}" class="${x.id===pg.id?'current':s.visited.includes(x.id)?'seen':''}" ${!C.canVisit(s,x.id,teacher)?'disabled':''} aria-label="${e(x.title.en)}" ${x.id===pg.id?'aria-current="step"':''}></button>`).join('')}</div>${s.access==='waiting'&&['main1','main2','save'].includes(pg.group)?`<div class="notice warning">${t('MIT access is still waiting. Prepare the words below and use the guide. These steps will stay marked “Awaiting MIT access”.','MIT 账户仍待处理。先准备文字并阅读指南，这些步骤会标为“等待 MIT 登录”。')}<button data-go="mit-signin" class="text-button">${t('Access working now? Return to sign-in','现在能登录了吗？返回登录步骤')}</button></div>`:''}<article class="slide ${pg.type==='learning'?'learning-slide':''}" aria-labelledby="slide-title">${pg.type==='learning'?learningPage(pg):`<h1 id="slide-title">${p(pg.title)}</h1>${renderPage(pg)}`}</article>${teacher?teacherPanel(pg):''}${footer(pg)}</main></div>`;}
function instruction(v){return `<p class="instruction">${p(v)}</p>`;}
function guidedTip(pg){if(!s.guided)return '';let tip=pg.type==='edit'?['Start by finding '+pg.component+'. Then change only the words shown in this step.','先找到 '+pg.component+'，再只修改这一步指定的文字。']:['Do the first action, compare your screen with the picture, then do the next action.','先做第一个动作，对照图片，再做下一个动作。'];return `<div class="support-tip"><b>${t('Start here','从这里开始')}</b> ${t(...tip)}</div>`;}
function renderPage(pg){switch(pg.type){
case 'mission':return `<div class="mission-grid"><div><div class="purpose-card"><span class="eyebrow">WAGBA</span><p>${p(D.wagba)}</p></div><div class="task-outcomes"><section><span>1</span><div><h2>${t('Make the homepage yours','做出自己的首页')}</h2><p>${t('Change the title, introduction, picture and button words to fit YOUR topic.','按自己的主题修改标题、简介、图片和按钮文字。')}</p></div></section><section><span>2</span><div><h2>${t('Make your button do something','让按钮完成一件事')}</h2><p>${t('Tap it to display a useful short message on the same homepage.','点击后，在同一首页显示一条有用的简短信息。')}</p></div></section></div><div class="notice">${t('Use the same imported project throughout. Today is the first version of your idea.','全程修改同一个导入项目。今天先做出创意的第一个版本。')}</div></div><div>${figure('01','The supplied starter. You will personalise it. 起始项目，你会把它改成自己的应用。')}</div></div>`;
case 'components':return `${instruction(D.pair('A component is one part of an app’s screen. Read each name and its job below. These names will help you find the right part in MIT.','组件是应用画面中的一个部分。阅读下面的名称和作用，之后用这些名称在 MIT 找到正确的组件。'))}<div class="mission-grid component-reference"><div class="component-cards">${[['Label','标签','Displays words, such as a title or a response.','显示文字，例如标题或响应信息。','TitleLabel · IntroLabel · ResponseLabel'],['Image','图片','Displays a picture for your topic.','显示与主题有关的图片。','AppImage'],['Button','按钮','Lets the user tap to start an action.','让用户通过点击来触发动作。','ActionButton · ResetButton']].map(([en,zh,desc,zhDesc,names])=>`<section class="card"><h2>${t(en,zh)}</h2><p>${t(desc,zhDesc)}</p><small>${e(names)}</small></section>`).join('')}</div>${figure('01','The starter contains labels, an image and buttons. 起始项目含有标签、图片和按钮。')}</div>`;
case 'demo':return demoPage();
case 'quiz':return quizPage(pg);
case 'focus':return focusPage();
case 'route':return `${instruction(D.pair('First, look for the homepage sketch you made in the previous theory lesson. Check your paper sketch, saved design PDF or theory work submitted in Teams. Then choose below.','先找出你在上一节理论课画的首页草图。查看纸上草图、保存的设计 PDF，或已在 Teams 提交的理论课作品，然后选择下面的路线。'))}<div class="route-grid">${choice('route','sketch',t('I found my theory sketch','我找到理论课的草图了'),t('Open it or keep the paper beside you. Use this design today and choose ONE of its buttons to make work.','打开草图，或把纸上草图放在旁边。今天沿用这个设计，先实现其中一个按钮。'),'✎')}${choice('route','quick',t('I do not have my theory sketch','我没有理论课的草图'),t('Missed theory or cannot find it? The next step helps you choose a topic and some starting words.','没上理论课或找不到草图？下一步会帮助你选择主题和起始文字。'),'✦')}</div><div class="notice">${t('A first working version is enough: one homepage with one useful tap-to-message feature.','先完成一个能运行的版本：一个首页，加一个点击显示信息的功能。')}</div>`;
case 'topics':return `${instruction(D.pair('Choose an idea you enjoy, or choose your own. These are examples, not a fixed app assignment.','选择自己喜欢的想法，也可以自选主题。这些只是示例，不是指定题目。'))}<div class="topic-grid"><button class="topic-card own-topic ${s.topic==='own'?'selected':''}" data-topic="own" aria-pressed="${s.topic==='own'}"><span aria-hidden="true">✦</span><strong>${t('My own idea','我自己的创意')}</strong><small>${t('Sport, music, books, a product, a place…','运动、音乐、书、产品、地点……')}</small></button>${D.topics.map(x=>`<button class="topic-card ${s.topic===x.id?'selected':''}" data-topic="${x.id}" aria-pressed="${s.topic===x.id}"><div style="background:${x.colour}"><img src="assets/art/${x.id}.svg" alt="${e(x.name.en)}"></div><strong>${p(x.name)}</strong><small>${t(x.button,({fashion:'查看穿搭',gaming:'查看手柄介绍',camera:'显示摄影小技巧',weather:'显示天气提示',booking:'显示一个活动',planner:'显示下一个活动'})[x.id])}</small></button>`).join('')}</div><p class="quiet-caption">${t('The first button will show information on the same screen. You can build other features in later lessons.','第一个按钮先在同一页面显示信息，其他功能可在后续课程继续制作。')}</p>`;
case 'name':return `${instruction(D.pair(s.route==='sketch'?'Use the name on your sketch, or change it. Short and memorable is a good start.':'Give your idea a short, memorable name. You can change the suggested name.',s.route==='sketch'?'使用草图上的名称，也可以修改。先用一个简短、好记的名字。':'给创意起个简短、好记的名字。你可以修改建议名称。'))}<div class="name-studio"><div class="card">${inputWord('title',t('My app’s name','我的应用名称'),'My App')}${C.topic(s)?`<button class="text-button" data-use-name="${e(C.topic(s).title)}">${t('Use starting name: '+C.topic(s).title,'使用起始名称：'+C.topic(s).title)}</button>`:''}<p class="small">${t('This is a note for your build. You will put it into TitleLabel in MIT.','这是制作时的笔记，稍后你会把它写进 MIT 的 TitleLabel。')}</p></div><div class="name-art"><img src="assets/art/${C.topic(s)?.id||'gaming'}.svg" alt="Creative topic illustration"><div class="name-preview" id="name-preview">${e(s.words.title||'Your app name')}</div></div></div>`;
case 'device':return `${instruction(D.pair('Choose the equipment you have in school today. Phones are not used in school, and you do not need one for this lesson.','选择你今天在学校使用的设备。学校不使用手机，这节课也不需要手机。'))}<div class="route-grid three">${choice('device','ipad',t('One iPad','一台 iPad'),t('Build in the browser. If Companion is available, try the app on this same iPad.','在浏览器中制作。如果已安装 Companion，就在这台 iPad 上测试。'),'▯')}${choice('device','computer',t('Computer + an approved iPad','电脑 + 获老师允许使用的 iPad'),t('Build in the computer browser. Use Companion on an iPad your teacher allows you to use.','在电脑浏览器中制作，在老师允许使用的 iPad 上用 Companion 测试。'),'▣')}${choice('device','no-device',t('Computer only','只用电脑'),t('Build, edit and save your project. Record the Companion checks as “Not tried yet” until an approved iPad is available.','先制作、修改并保存项目。有可用且获老师允许的 iPad 前，把 Companion 测试记为“尚未尝试”。'),'▱')}</div>${s.device==='ipad'?`<div class="notice">${t('Use the iPad sideways and open MIT in a full browser. Find the one-iPad guide in Resources. If Companion is unavailable or will not connect, keep building in the browser, save your project and mark the live checks “Not tried yet”. Ask your teacher for help.','横放 iPad，用完整浏览器打开 MIT。资源里有单台 iPad 指南。如果没有 Companion 或无法连接，请继续在浏览器制作并保存项目，把运行测试标为“尚未尝试”，再向老师求助。')}</div>`:''}<p class="notice">${t('At home: if you have access to a suitable phone and permission to use it, you may use Companion to try your saved app. This is an extra opportunity, not a requirement for today’s school lesson.','在家：如果有合适的手机，并获允许使用，可以用 Companion 测试保存的应用。这是额外体验，不是今天在校上课的必需条件。')}</p>`;
case 'signin':return signinPage();
case 'download':return `<div class="work-layout"><div><span class="workspace-tag">${t('IN THIS LESSON','在本课网页中')}</span>${instruction(D.pair('Download the project file below. Keep its name and .aia ending. You will import it inside MIT in the next step.','下载下面的项目文件，保留文件名及 .aia 后缀。下一步会在 MIT 内导入它。'))}<a class="download-starter" href="assets/MyApp_W9.aia" download="MyApp_W9.aia" data-starter-download><span class="file-icon">.aia</span><span><strong>MyApp_W9.aia</strong><small>${t('Working homepage + two connected button programs','已有首页与两组连接好的按钮程序')}</small></span><b aria-hidden="true">↓</b></a>${s.downloaded?`<div class="feedback">${t('Download started. Check Downloads for MyApp_W9.aia before continuing.','已开始下载。继续前，请确认 Downloads 中有 MyApp_W9.aia。')}</div>`:''}${helpButton('files')}<div class="notice">${t('An .aia is the editable MIT project. Import it through MIT rather than double-clicking it to run.',' .aia 是可编辑的 MIT 项目文件，需通过 MIT 导入。')}</div></div>${figure('01','Your starter opens with these components. 起始项目包含这些组件。')}</div>`;
case 'guide':return guidePage(pg);
case 'edit':return editPage(pg);
case 'blocks':return blocksPage();
case 'connect':return connectPage();
case 'test':return testPage(pg);
case 'challenge':return challengePage();
case 'pit':return pitPage(pg);
case 'phase-summary':return phasePage();
case 'finish':return finishPage();
default:return '';}}
function choice(field,value,title,desc,icon){return `<button class="route-choice ${s[field]===value?'selected':''}" data-choice="${field}" data-value="${value}" aria-pressed="${s[field]===value}"><span class="route-icon" aria-hidden="true">${icon}</span><strong>${title}</strong><span>${desc}</span></button>`;}
function demoPage(){const x=D.topics.find(t=>t.id===s.demo.topic);return `${instruction(D.pair('Try the main button. Notice which words change. This lesson demo models the one-message feature you will build in MIT.','试按主按钮，注意哪些文字改变。这个课程演示展示了你将在 MIT 制作的信息功能。'))}<div class="demo-layout"><div class="phone"><div class="phone-screen"><small>${p(x.name)}</small><h2>${e(x.title)}</h2><img src="assets/art/${x.id}.svg" alt="${e(x.name.en)}"><p>${e(x.intro)}</p><button class="phone-button" data-action="demo-tap">${t(x.button,({fashion:'查看穿搭',gaming:'查看手柄介绍',camera:'显示摄影小技巧',weather:'显示天气提示',booking:'显示一个活动',planner:'显示下一个活动'})[x.id])}</button><p class="live-message ${s.demo.clicked?'changed':''}" role="status">${s.demo.clicked?t(x.response,x.zhResponse):t('Your response will appear here.','这里将显示响应信息。')}</p><button class="phone-reset" data-action="demo-reset">${t('Reset','重置')}</button></div></div><div><div class="cause-card"><span class="eyebrow">${t('THE USER’S EVENT','用户事件')}</span><h2>${t('Tap the button','点击按钮')}</h2><div class="flow-arrow" aria-hidden="true">↓</div><span class="eyebrow">${t('THE APP’S RESPONSE','应用响应')}</span><p class="response-preview" aria-live="polite">${s.demo.clicked?t(x.response,x.zhResponse):t('Try a tap to reveal the response.','点一下按钮，查看响应。')}</p></div><div class="demo-topics" aria-label="Demo topics">${D.topics.map(a=>`<button data-demo-topic="${a.id}" class="${a.id===x.id?'selected':''}" aria-pressed="${a.id===x.id}">${p(a.name)}</button>`).join('')}</div><p class="small muted">${t('Sample information. In your real build, use your own topic and message.','这里只是示例信息，实际制作时用自己的主题和信息。')}</p></div></div>`;}
function quizPage(pg){const q=D.quiz[pg.id],a=s.answers[pg.id],checked=s.attempted[pg.id];return `<div class="question-card"><fieldset><legend>${p(q.q)}</legend><p class="quiet-caption">${t('Choose one answer, then check it.','选择一个答案，再检查。')}</p><div class="quiz-options">${s.optionOrders[pg.id].map((id,i)=>{const o=q.options.find(o=>o.id===id);return `<label class="option ${a===id?'selected':''}"><input type="radio" name="quiz-${pg.id}" value="${e(id)}" data-answer="${pg.id}" ${a===id?'checked':''}><span class="option-letter" aria-hidden="true">${String.fromCharCode(65+i)}</span><span>${p(o)}</span></label>`;}).join('')}</div></fieldset><button class="button primary" data-check="${pg.id}" ${!a?'disabled':''}>${t('Check my answer','检查答案')}</button><div class="feedback-space" aria-live="polite">${checked?`<div class="feedback ${a===q.correct?'':'try-again'}"><strong>${a===q.correct?t('Yes — that fits.','对，符合这个用途。'):t('Look at the difference.','再看看它们的区别。')}</strong><p>${p(q.explain)}</p>${a!==q.correct?`<p>${t('You can choose again and check once more.','你可以重新选择，再检查一次。')}</p>`:''}</div>`:''}</div></div>`;}
function learningPage(pg){const c=D.checks.find(x=>x.id===pg.check);return `<div class="learning-target"><span class="ksu-letter">${c.area}</span><div><span class="eyebrow">${p(D.areas[c.area])} · ${t('MY STARTING POINT','我的起点')}</span><h1 id="slide-title">${p(c.q)}</h1><p>${p(c.hint)}</p></div></div><fieldset class="reflection-options"><legend>${t('Choose the statement that fits you now.','选择符合你现在情况的说法。')}</legend>${D.starting.map(x=>`<label class="option ${s.learning[c.id]===x.id?'selected':''}"><input type="radio" name="learning-${c.id}" value="${x.id}" data-learning="${c.id}" ${s.learning[c.id]===x.id?'checked':''}><span>${p(x)}</span></label>`).join('')}</fieldset>`;}
function focusPage(){const f=C.focus(s),untried=D.checks.filter(x=>s.learning[x.id]==='untried').length,secure=D.checks.filter(x=>s.learning[x.id]==='secure').length;return `<div class="focus-card"><span class="eyebrow">${t('YOUR CHECKS, YOUR NEXT FOCUS','根据自己的检查，选择学习重点')}</span><h2>${f.winners.length?p(D.pair(f.winners.map(a=>D.areas[a].en).join(' + '),f.winners.map(a=>D.areas[a].zh).join(' + '))):t('Use today’s build to find your next step','用今天的制作找到下一步')}</h2><p>${f.winners.length?t((f.winners.length>1?'These areas are tied for your highest count. ':'This area has your highest count. ')+'You marked more checks here as new or needing help. Use the examples and practise these parts as you build.',(f.winners.length>1?'这些领域的最高计数相同。':'这个领域的计数最高。')+'你在这些方面选了新内容或需要帮助。制作时多参考示例，练习这些部分。'):t('You have not marked a particular area as new or needing help. Familiar things count as prior learning; you do not need to choose them as a target again.','你没有把某个领域标为新内容或需要帮助。熟悉的内容算已有基础，不必自动成为今天的目标。')}</p><div class="count-grid">${['K','S','U'].map(a=>`<div class="${f.winners.includes(a)?'highest':''}"><b>${f.counts[a]||0}<small>/2</small></b><span>${p(D.areas[a])}</span><small>${t('new / need help','新内容／需要帮助')}</small></div>`).join('')}</div></div><p class="notice">${t(secure+' of 6 checks feel familiar. '+untried+(untried===1?' is':' are')+' not tried yet. “Not tried” is recorded separately; it is not a wrong answer.',6+' 项中，'+secure+' 项已经熟悉，'+untried+' 项尚未尝试。“尚未尝试”单独记录，不算答错。')}</p><div class="next-focus-grid">${['K','S','U'].map(a=>`<section><b>${p(D.areas[a])}</b><p>${t(...({K:['Match each new word to a real component in the pictures.','把新词与截图中的实际组件对应起来。'],S:['Follow one screenshot, make one change, then check the screen.','跟着一张截图做一个修改，再检查画面。'],U:['Connect the button’s promise to what the user actually sees.','把按钮承诺的用途与用户实际看到的结果联系起来。']})[a])}</p></section>`).join('')}</div>`;}
function signinPage(){return `<div class="work-layout"><div><span class="workspace-tag">${t('OPEN MIT IN ANOTHER TAB','在另一个标签页打开 MIT')}</span>${instruction(D.pair('Use your school email and your separate MIT password. Keep this lesson open so you can return to the next step.','使用学校邮箱和独立的 MIT 密码，保留本课网页，以便回来继续。'))}${ext('https://login.appinventor.mit.edu/login/',t('Open MIT school-email login','打开 MIT 学校邮箱登录'),'button primary external')}<p class="small">${t('Your school email can be Microsoft/Teams email. You do not need to use the Google-only sign-in route.','学校邮箱可以是 Microsoft／Teams 邮箱，不必使用只支持 Google 的登录页面。')}</p>${helpButton('access',t('First visit? Account setup guide','第一次使用？看账户设置指南'))}<fieldset class="compact-check"><legend>${t('What can you see in MIT?','你在 MIT 看到了什么？')}</legend>${['ready','waiting'].map((id,i)=>`<label class="option"><input type="radio" name="access" data-access value="${id}" ${s.access===id?'checked':''}><span>${t(...(i?['I need access help. I will prepare my app’s words while waiting.','我需要登录帮助，等待时先准备应用文字。']:['My Projects or an existing project is open.','已打开 My Projects 或已有项目。']))}</span></label>`).join('')}</fieldset></div>${figure('03','The school-email login. Use the MIT password you set for this service. 学校邮箱登录入口。')}</div>`;}
function guidePage(pg){const noCompanion=pg.id==='connection-code'&&s.device==='no-device',pending=noCompanion?'<div class="notice warning">'+t('Computer only in school: read this guide for later. On the next two button checks, choose “I have not tried it in Companion yet”, then save your project.','在学校只用电脑：先阅读指南以备之后使用。接下来两个按钮检查都选“我还没有在 Companion 中尝试”，然后保存项目。')+'</div>':'';const hint=pg.id==='edit-image'?`<div class="image-bank">${D.topics.map(x=>`<div><img src="assets/art/${x.id}.svg" alt="${e(x.name.en)}"><span>${x.id}.png</span></div>`).join('')}</div>`:'';return `<div class="work-layout"><section><span class="workspace-tag">${noCompanion?t('REFERENCE FOR LATER','留待之后参考'):t('DO THIS IN MIT','在 MIT 中操作')}</span>${pending}${!noCompanion?instruction(pg.instruction):''}${guidedTip(pg)}${hint}<div class="checkpoint"><b>${noCompanion?t('Your next step','你的下一步'):t('Look for this','完成后应该看到')}</b><p>${noCompanion?t('Continue with your build and save it. A live result can be checked later on an approved iPad, or at home with a suitable phone and permission.','继续完成并保存项目。之后可用获老师允许的 iPad，或在家有合适手机且获允许时，检查实际运行结果。'):p(pg.checkpoint)}</p></div>${helpButton(pg.help)}</section><section>${figure(pg.guide,pg.title.en+' / '+pg.title.zh)}${pg.guide==='14'?`<p class="source-note">${t('The Companion view is from MIT’s official iPad demonstration (older interface). Connection details in the guide are hidden.','Companion 画面来自 MIT 官方 iPad 演示（旧界面），指南已隐藏连接信息。')}</p>`:''}</section></div>`;}
function editPage(pg){const key=pg.word,topic=C.topic(s),placeholder=topic?.[key]||({title:'Your app name',intro:'Ideas and information about my topic.',button:'Show an idea',response:'One useful idea for my user.'})[key];return `<div class="work-layout"><section><span class="workspace-tag">${t('DO THIS IN MIT','在 MIT 中操作')}</span>${instruction(pg.instruction)}${guidedTip(pg)}<div class="words-card"><span class="eyebrow">${t('WORDS FOR YOUR MIT BUILD','给 MIT 制作准备的文字')}</span>${inputWord(key,t(...({title:['My app name','应用名称'],intro:['My short introduction','简短介绍'],button:['My button words','按钮文字'],response:['My button’s message','按钮显示的信息']})[key]),placeholder)}<div class="word-actions"><button class="button small" data-copy="${key}" ${!s.words[key].trim()?'disabled':''}>${t('Copy these words','复制这些文字')}</button>${topic?`<button class="text-button" data-use-word="${key}">${t('Use the starting example','使用起始示例')}</button>`:''}</div><p class="small muted">${t('These are notes. Paste or type the words into the MIT field shown in the screenshot.','这些是笔记，请把文字粘贴或输入到截图标出的 MIT 输入框。')}</p></div><div class="checkpoint"><b>${t('Look for this','完成后应该看到')}</b><p>${p(pg.checkpoint)}</p></div>${helpButton(pg.help)}</section><section>${figure(pg.guide,pg.title.en+' / '+pg.title.zh)}${pg.id==='edit-response'?`<div class="matching-note"><small>${t('Your button says','你的按钮写着')}</small><strong>${e(s.words.button||'Your action')}</strong><span aria-hidden="true">↓</span><p>${t('Your message should give the user what those words promise.','信息应实现按钮文字承诺的用途。')}</p></div>`:''}</section></div>`;}
function blocksPage(){const parts=[{title:D.pair('1 · The event','1 · 事件'),body:D.pair('when ActionButton.Click means: when the user taps the main button, run the instructions inside this event handler.','when ActionButton.Click 的意思是：当用户点击主按钮，就运行里面的指令。')},{title:D.pair('2 · The instruction','2 · 指令'),body:D.pair('set ResponseLabel.Text means: replace the words shown by ResponseLabel. The label is the area under your main button.','set ResponseLabel.Text 的意思是：替换 ResponseLabel 显示的文字，也就是主按钮下方的响应区域。')},{title:D.pair('3 · The message','3 · 信息'),body:D.pair('The connected pink text block holds the exact message the label will display. This is the part you will change next.','连接好的粉色文字积木中保存了要显示的信息。下一步你会修改这里。')}],x=parts[s.tutor];return `${instruction(D.pair('Choose Blocks at the top right in MIT. Your starter already has these two connected event handlers. Follow the three highlights to read the top one.','在 MIT 点右上角 Blocks。起始项目已经有两组连接好的事件程序，跟着三个重点读懂上方程序。'))}<div class="block-tutor"><div class="block-image">${figure('11','Real connected blocks in the starter. 起始项目中真实连接好的积木。')}<div class="tutor-overlay" aria-hidden="true"><div class="tutor-marker m${s.tutor}"></div></div></div><section class="tutor-explanation" aria-live="polite"><span class="eyebrow">${t('FOLLOW THE PROGRAM','跟着程序读一读')}</span><h2>${p(x.title)}</h2><p>${p(x.body)}</p><div class="tutor-buttons">${parts.map((a,i)=>`<button data-tutor="${i}" class="${s.tutor===i?'selected':''}" aria-pressed="${s.tutor===i}">${i+1}</button>`).join('')}</div><p class="small">${t('The lower handler is for Reset. Keep it unchanged while you build the first response.','下方程序负责 Reset，制作第一个响应时先保持不变。')}</p></section></div>`;}
function connectPage(){const later=s.device==='no-device',intro=later?D.pair('You chose Computer only. Read the connection picture for later, then continue. On each of the next two button checks, select “I have not tried it in Companion yet”. You can still edit, save and export your project today.','你选择了只用电脑。先阅读连接示意图以备之后使用，再继续。接下来两个按钮检查都选“我还没有在 Companion 中尝试”。今天仍可修改、保存和导出项目。'):s.device==='ipad'?D.pair('Use the same iPad for the MIT browser editor and Companion. Open the official MIT App Inventor Companion first. In MIT, choose Connect, then AI Companion. Follow the one-iPad picture guide below.','在同一台 iPad 上使用 MIT 浏览器编辑器与 Companion。先打开官方 MIT App Inventor Companion，再在 MIT 选择 Connect，然后选 AI Companion，按下方单台 iPad 图解操作。'):D.pair('Open MIT App Inventor Companion on the iPad your teacher has approved. Use the same Wi-Fi as your computer. In the computer’s MIT editor, choose Connect, then AI Companion.','先在老师允许使用的 iPad 上打开官方 MIT App Inventor Companion，连接与电脑相同的 Wi-Fi。在电脑的 MIT 编辑器选择 Connect，再选 AI Companion。');return `<div class="work-layout"><section><span class="workspace-tag">${later?t('REFERENCE FOR LATER','留待之后参考'):t('EDITOR + IPAD COMPANION','编辑器 + iPad Companion')}</span>${instruction(intro)}${ext('https://appinventor.mit.edu/ios_tips',t('Official iPad Companion information','官方 iPad Companion 说明'),'button')}${!later?`<p class="small">${t('Have Companion ready before requesting the six-letter code. Use the current code from your editor, not a screenshot.','先准备好 Companion，再获取六位字母码。使用自己编辑器中的当前连接码，不用截图中的旧码。')}</p>`:''}${s.device==='ipad'?`<div class="notice">${t('Use the available iPad window controls to keep the browser and Companion open together. If Companion is unavailable or switching apps disconnects it, save your project and leave the live checks as “Not tried yet”. Ask your teacher for help.','用 iPad 支持的窗口功能同时保留浏览器与 Companion。如果没有 Companion，或切换应用导致断线，请保存项目，把运行测试标为“尚未尝试”，再向老师求助。')}<button class="text-button" data-guide="I3">${t('Open the single-iPad guide','打开单台 iPad 指南')}</button></div>`:''}<p class="small">${t('No phones in school. Phone testing is only an extra option at home, if you have access and permission.','在校不使用手机。手机测试只是在家有设备且获允许时的额外选择。')}</p>${helpButton('connection')}</section>${figure('13','Connect > AI Companion in the actual MIT editor. 在 MIT 连接 AI Companion。')}</div>`;}
function testPage(pg){const reset=pg.test==='reset',resetMessage=s.words.reset?.trim()||'Your response will appear here.',testInstruction=reset&&s.words.reset?.trim()?D.pair('In Companion, tap Reset. Check that your new starting message returns: '+resetMessage,'在 Companion 点 Reset，检查新的起始信息是否恢复：'+resetMessage):pg.instruction;return `<div class="test-layout"><div><span class="workspace-tag">${s.device==='no-device'?t('LIVE CHECK FOR LATER','留待之后实际测试'):t('DO THIS IN COMPANION','在 COMPANION 中操作')}</span>${instruction(s.device==='no-device'?D.pair('You are building on a computer without Companion in school. Read the expected result on this page, choose “I have not tried it in Companion yet”, and continue. You can still save and export your app.','你正在学校只用电脑制作，没有 Companion。先阅读本页的预期结果，选择“我还没有在 Companion 中尝试”，然后继续。你仍可保存和导出应用。'):testInstruction)}${s.device==='ipad'?`<div class="notice">${t('No Companion available in school, or unable to connect? Choose “I have not tried it in Companion yet” below and continue to save your project. This is not a failed test.','在学校没有可用的 Companion，或无法连接？选择下方“我还没有在 Companion 中尝试”，再继续保存项目。这不算测试失败。')}</div>`:''}<fieldset><legend>${t('What happened when you tried it?','实际尝试后，发生了什么？')}</legend>${[
 ['done',reset?t('Reset showed the expected starting message.','Reset 显示了预期的起始信息。'):t('The label showed my new message.','标签显示了我的新信息。')],
 ['needs-fix',t('I tried it, but the response was different.','我试过了，但响应不一样。')],
 ['not-tried',t('I have not tried it in Companion yet.','我还没有在 Companion 中尝试。')]
].map(([id,label])=>`<label class="option"><input type="radio" data-test="${pg.id}" name="${pg.id}" value="${id}" ${s.work[pg.id]===id?'checked':''}><span>${label}</span></label>`).join('')}</fieldset>${s.work[pg.id]==='needs-fix'?`<div class="feedback try-again">${t('Compare the pink text block in the correct handler with the message you saw. Check that its component is ResponseLabel.','对照对应事件程序中的粉色文字与实际信息，检查组件是否为 ResponseLabel。')}${helpButton(reset?'reset':'blocks')}</div>`:''}</div><div class="expected-result"><span class="eyebrow">${t('WHAT YOU ARE LOOKING FOR','你要检查的结果')}</span><div class="result-button">${e(reset?'Reset':s.words.button||'Your main button')}</div><span class="flow-arrow">↓</span><div class="result-message">${e(reset?resetMessage:s.words.response||'The message you wrote in your pink text block.')}</div><p class="small">${t('This panel describes the expected result. Look for the actual result in Companion.','右边说明预期结果，实际结果请在 Companion 中查看。')}</p></div></div>`;}
function challengePage(){return `${instruction(D.pair('If your core app is saved and you have time, keep creating. Choose one change to make in the SAME project.','如果主要功能已经保存，而且还有时间，请继续创作，在同一个项目中选择一个改动。'))}<div class="route-grid">${choice('challenge','image',t('Use your own image','使用自己的图片'),t('Give the homepage a picture that fits your own idea.','为首页选一张真正符合自己创意的图片。'),'▧')}${choice('challenge','reset',t('Personalise the Reset message','改成自己的重置信息'),t('Make the message after Reset fit your app’s voice.','让重置后的信息也有你的应用风格。'),'↺')}</div>${s.challenge?`<div class="challenge-work card"><span class="workspace-tag">${t('IN THE SAME MIT PROJECT','在同一个 MIT 项目中')}</span>${s.challenge==='image'?`<ol><li>${t('Choose AppImage, then Picture. Select Upload File to add your own suitable image.','选 AppImage，再开 Picture，通过 Upload File 上传自己的合适图片。')}</li><li>${t('Choose that image and OK. In AlternateText, describe the picture briefly.','选择新图片并点 OK，在 AlternateText 中简短描述图片。')}</li><li>${t('Check it fits the homepage and save the project again.','检查图片在首页的显示，再保存一次项目。')}</li></ol>${helpButton('image')}`:`<ol><li>${t('In Designer, choose ResponseLabel. Change Text to your starting message from the box below.','在 Designer 选 ResponseLabel，把 Text 改成下方输入框里准备的起始信息。')}</li><li>${t('In Blocks, change the pink text in ResetButton.Click to EXACTLY the same starting message. Keep ActionButton.Click separate.','在 Blocks，把 ResetButton.Click 内的粉色文字改成完全相同的起始信息，别改错 ActionButton.Click。')}</li><li>${t('If Companion is available on your school iPad, try the main button, then Reset. Otherwise leave the live check untried. Save the changed project either way.','若学校使用的 iPad 有 Companion，先试主按钮，再试 Reset。否则保留测试为尚未尝试。不论能否测试，都保存修改后的项目。')}</li></ol>${inputWord('reset',t('My new starting / Reset message','新的起始／重置信息'),'Ready? Tap the button for an idea.')}<button class="button small" data-copy="reset" ${!s.words.reset?.trim()?'disabled':''}>${t('Copy this message','复制这条信息')}</button>${helpButton('reset')}<label class="option challenge-check"><input type="checkbox" data-test="try-reset" value="done" ${s.work['try-reset']==='done'?'checked':''}><span>${t('I tried this changed Reset in Companion. It showed my new starting message.','我在 Companion 试过修改后的 Reset，它显示了我的新起始信息。')}</span></label>`}</div>`:`<p class="notice">${t('Still finishing the core app? Continue your current MIT step, then come back here if time remains.','还没完成主要功能？先继续当前 MIT 步骤，有时间再回来。')}</p>`}`;}
function pitPage(pg){const a=pg.area;return `<div class="learning-target"><span class="ksu-letter">${a}</span><div><span class="eyebrow">${p(D.areas[a])}</span><p>${p(D.targets[a])}</p></div></div><fieldset class="phase-options"><legend>${t('Choose how this part of your learning feels now.','选择你现在对这部分学习的状态。')}</legend><div class="phase-grid">${D.phases.map((x,i)=>`<label class="phase ${s.pit[a]===x.id?'selected':''}"><input type="radio" name="phase-${a}" data-pit="${a}" value="${x.id}" ${s.pit[a]===x.id?'checked':''}><span><strong>${p(x.name)}</strong><small>${p(x.desc)}</small></span><b aria-hidden="true">${['↗','↻','→','?'][i]}</b></label>`).join('')}</div></fieldset>`;}
function phasePage(){const r=C.dominant(Object.values(s.pit)),w=r.winners[0],phase=D.phases.find(p=>p.id===w);return `<div class="phase-result"><span class="eyebrow">${t('BASED ON YOUR THREE CONFIDENCE CHOICES','根据三个领域的信心选择')}</span><h2>${r.winners.length===1?p(phase.name):t('Your areas are in different phases','不同领域，学习状态不同')}</h2><p>${r.winners.length===1?t('You chose this most often: '+r.max+' of '+r.total+' areas. This describes your experience, not a test score.','这是你选择最多的状态：'+r.total+' 个领域中的 '+r.max+' 个。它描述学习体验，不是考试分数。'):t('There is a tie. You do not need to put all your learning into one phase.','计数相同，不需要把所有学习都归成一种状态。')}</p><div class="phase-counts">${D.phases.map(x=>`<div><b>${r.counts[x.id]||0}</b><span>${p(x.name)}</span></div>`).join('')}</div></div><div class="area-results">${['K','S','U'].map(a=>{const x=D.phases.find(x=>x.id===s.pit[a]);return `<section class="${x?.id==='stuck'?'needs-help':''}"><b>${p(D.areas[a])}</b><h3>${x?p(x.name):t('Not selected','未选择')}</h3><p>${x?p(x.next):t('Return to the previous steps to choose this area.','返回前面的步骤选择这个领域。')}</p></section>`;}).join('')}</div>`;}
function finishPage(){return `${instruction(D.pair('Keep your edited MIT project first. Then save this short learning record as a PDF and submit the files your teacher asks for in Teams.','先保留修改后的 MIT 项目，再把本课学习记录保存为 PDF，按老师要求在 Teams 提交文件。'))}<div class="finish-grid"><div class="save-primary card"><span class="eyebrow">${t('YOUR FINISHED BUILD','你的制作成果')}</span><h2>${e(s.words.title||'My first app')}</h2><p>${e(s.words.button||'My main button')} <span aria-hidden="true">→</span> ${e(s.words.response||'My own message')}</p><ul class="finish-checks"><li>${t('An edited .aia keeps the actual app code. Export it from MIT.','修改后的 .aia 保留真正的应用程序，请从 MIT 导出。')}</li><li>${t('This PDF records your words, checked steps and learning reflections.','本课 PDF 记录应用文字、操作检查和学习反思。')}</li></ul><button class="button primary large" data-action="pdf">${t('Save my learning record as PDF','把学习记录保存为 PDF')} ↓</button><p class="small">${t('In the print window, choose Save as PDF. On iPad, open the print preview, then Share and Save to Files.','电脑在打印窗口选择另存为 PDF；iPad 可打开打印预览，再共享并存储到文件。')}</p><div class="notice">${t('Then open your class’s Teams assignment. Attach your edited .aia and learning PDF as requested, and select Turn in.','然后打开班级 Teams 作业，按要求附上修改后的 .aia 和学习 PDF，选择提交。')}</div></div><div><div class="card"><h2>${t('Your work status','作品状态')}</h2><details class="status-details"><summary>${t('Review completed and untried steps','查看已完成与尚未尝试的步骤')}</summary>${workSummary()}</details><p class="small muted">${t('These are your own checks. Moving through the lesson does not prove the MIT app works.','这些是你自己的操作记录，浏览完网页不等于 MIT 应用已经运行成功。')}</p></div><details class="backup-tools"><summary>${t('Backup and readable report','备份与可读报告')}</summary><p>${t('A backup reopens this lesson’s progress. A readable report opens the record without printing. Neither replaces the MIT .aia project.','备份可恢复本课网页进度，可读报告便于查看记录；两者都不能代替 MIT 的 .aia 项目。')}</p><button class="button small" data-action="backup">${t('Download progress backup','下载进度备份')}</button><button class="button small" data-action="read-report">${t('Open readable report','打开可读报告')}</button></details></div></div>`;}
function workSummary(){const ids=['edit-title','edit-intro','edit-image','edit-button','edit-response','try-button','try-reset','save-project','export-project','reopen-project'];return `<ul class="work-summary">${ids.map(id=>{const pg=D.pages.find(p=>p.id===id),status=s.work[id]||'not-tried',labels={done:['Checked by me in MIT','我已在 MIT 检查'],help:['Help requested','需要帮助'],'not-tried':['Not tried yet','尚未尝试'],'awaiting-access':['Awaiting MIT access','等待 MIT 登录'],'needs-fix':['Tried; needs a fix','已尝试，需要修改']};return `<li><span>${p(pg.title)}</span><b class="status-${status}">${t(...labels[status])}</b></li>`;}).join('')}</ul>`;}
function teacherPanel(pg){const q=D.quiz[pg.id],note=D.teacherNotes[pg.id]||D.pair('Keep students working in the same imported project. Ask them to show the changed component or response before supplying another explanation. The screenshot guide is available beside each MIT action.','让学生一直修改同一个导入项目。先请学生展示改动的组件或响应，再提供解释。每个 MIT 操作旁都有截图指南。');return `<details class="teacher-notes"><summary>Teacher notes · ${e(pg.group)}</summary><p>${p(note)}</p>${q?`<p><b>Answer:</b> ${p(q.options.find(o=>o.id===q.correct))}</p>`:''}<p>Teacher view unlocks navigation. It does not mark student work complete.</p></details>`;}
function allowedNext(pg){if(pg.type==='quiz')return !!s.attempted[pg.id];if(pg.type==='learning')return !!s.learning[pg.check];if(pg.type==='route')return !!s.route;if(pg.type==='name')return !!s.words.title.trim();if(pg.type==='device')return !!s.device;if(pg.type==='signin')return !!s.access;if(pg.type==='download')return s.downloaded;if(pg.type==='pit')return !!s.pit[pg.area];if(pg.type==='test')return !!s.work[pg.id];return true;}
function footer(pg){const a=C.path(s),i=a.findIndex(x=>x.id===pg.id),isMIT=['guide','edit','blocks','connect'].includes(pg.type),pending=C.statusFor(s,pg)!=='done';const nextLabel=isMIT?(pending?t('Continue with the guide','继续看指南'):t('I’ve done this · Next','已完成 · 下一步')):t('Next step','下一步');return `<footer class="slide-nav"><button class="button subtle" data-action="previous" ${i<=0?'disabled':''}>← ${t('Back','上一步')}</button><span class="slide-counter">${t('One step at a time','每次专注一步')}<small>${i+1} / ${a.length}</small></span>${pg.id==='finish'?'<span></span>':`<button class="button primary" data-action="next" ${!allowedNext(pg)&&!teacher?'disabled':''}>${nextLabel} →</button>`}</footer>`;}
function render(moveFocus=false){const old=document.activeElement,radio=old?.type==='radio'?{name:old.name,value:old.value}:null;app.innerHTML=s.joined?frame():landing();document.documentElement.lang=s.lang==='bi'?'en':'en';document.body.classList.toggle('bilingual',s.lang==='bi');document.body.classList.toggle('guided',s.guided);if(moveFocus){document.querySelector('#main')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}else if(radio){document.querySelector('input[name="'+CSS.escape(radio.name)+'"][value="'+CSS.escape(radio.value)+'"]')?.focus({preventScroll:true});} }
function setHash(id){const target='#'+encodeURIComponent(id);if(location.hash!==target)history.pushState(null,'',location.pathname+location.search+target);}
function navigate(id){if(!C.visit(s,id,teacher)){toast('Finish the earlier steps first.','请先完成前面的步骤。');return;}setHash(id);save();render(true);}
function goNext(){const pg=active();if(!allowedNext(pg)&&!teacher)return;if(!teacher&&['guide','edit','blocks','connect'].includes(pg.type))s.work[pg.id]=C.statusFor(s,pg);C.advance(s);setHash(s.slide);save();render(true);}
function showDialog(html){const wasOpen=dialog.open;if(!wasOpen)focusReturn=document.activeElement;document.querySelector('#dialog-content').innerHTML=`<div class="dialog-top"><h2 id="dialog-title">${t('Studio guide','创作室指南')}</h2><button class="button small" data-action="close-dialog" aria-label="Close">${t('Close','关闭')} ×</button></div>${html}`;if(!dialog.open)dialog.showModal();else document.querySelector('[data-action="close-dialog"]')?.focus();}
function closeDialog(){dialog.close();if(focusReturn?.isConnected)focusReturn.focus();else document.querySelector('#main')?.focus({preventScroll:true});}
function showGuide(id){const rowTitle=D.pages.find(p=>p.guide===id)?.title;showDialog(`<h3>${rowTitle?p(rowTitle):t('Step-by-step reference','步骤参考')}</h3><img class="full-guide" src="assets/guides/${e(id)}.png" alt="${e(rowTitle?.en||'Bilingual annotated guide')}"><p class="small">${t('Genuine MIT screenshots with teaching annotations. iPad reference frames are identified on the guide.','真实 MIT 截图加教学标注。iPad 参考画面的来源已在指南注明。')}</p><a class="button" href="assets/MIT_Practical_Guide_EN_ZH.pdf" target="_blank" rel="noopener">${t('Open the complete PDF guide','打开完整 PDF 指南')}</a>`);}
function showHelp(id){const h=D.help[id]||D.help.designer;showDialog(`<h3>${p(h.title)}</h3><ol class="help-steps">${h.steps.map(x=>`<li>${p(x)}</li>`).join('')}</ol><div class="help-guides">${h.guides.map(g=>`<button class="button small" data-guide="${g}">${t('Picture guide '+g,'图解 '+g)} ⤢</button>`).join('')}</div><div class="notice">${t('Still stuck? Keep this step marked for help and continue. It will not be recorded as completed in MIT.','仍然卡住？把这一步记录为需要帮助，然后继续；它不会被记为已在 MIT 完成。')}</div><button class="button primary" data-flag="${id}">${t('Record help needed · Continue','记录需要帮助 · 继续')}</button>`);}
function resources(){showDialog(`<div class="resource-grid"><a href="assets/MyApp_W9.aia" download class="resource-card"><b>.aia</b><strong>${t('Working MIT starter','MIT 起始项目')}</strong><p>MyApp_W9.aia</p></a><a href="assets/MIT_Practical_Guide_EN_ZH.pdf" target="_blank" rel="noopener" class="resource-card"><b>PDF</b><strong>${t('English–Mandarin screenshot guide','英中双语截图指南')}</strong><p>${t('Core steps plus account and iPad help','主步骤、账户与 iPad 帮助')}</p></a></div><h3>${t('Get help with…','查看这些帮助……')}</h3><div class="help-guides">${Object.entries(D.help).map(([id,x])=>`<button class="button small" data-help="${id}">${p(x.title)}</button>`).join('')}<button class="button small" data-guide="I3">${t('One-iPad guide','单台 iPad 指南')}</button></div><h3>${t('Your lesson progress','你的课程进度')}</h3><p class="small">${t('Backup files are for this lesson’s notes. Save the app itself as an .aia in MIT.','备份文件保存本课笔记，应用本身需要在 MIT 保存为 .aia。')}</p><div class="button-row"><button class="button small" data-action="backup">${t('Download progress backup','下载进度备份')}</button><button class="button small" data-action="import-backup">${t('Restore a progress backup','恢复进度备份')}</button></div>${s.visited.length?`<button class="text-button" data-action="new-record">${t('Start a new learner record','开始新同学的记录')}</button>`:''}<p class="source-note">MIT screenshots and official reference frames: Massachusetts Institute of Technology, CC BY-SA 4.0. Cropped and annotated. Topic images and lesson text: CS with Mr Dave.</p>`);}
function download(data,name,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
async function copyWord(key){const value=s.words[key];if(!value?.trim())return;try{await navigator.clipboard.writeText(value);toast('Copied. Paste into the matching MIT field.','已复制，请粘贴到对应的 MIT 输入框。');}catch(_){const input=document.querySelector(`[data-word="${key}"]`);input?.focus();input?.select();toast('The words are selected. Use your device’s Copy command.','文字已选中，请使用设备的复制功能。');}}
function report(print){save();document.title=(s.words.title||'My App')+' - Learning Record';reportMode=true;app.innerHTML=window.PracticalReport.render(s);document.querySelector('#print-record').onclick=()=>window.print();document.querySelector('#back-lesson').onclick=()=>{reportMode=false;s.slide='finish';setHash('finish');render(true);};if(print)document.fonts.ready.then(()=>requestAnimationFrame(()=>window.print()));}
document.addEventListener('click',ev=>{const b=ev.target.closest('button,a');if(!b)return;
 if(b.dataset.action){const action=b.dataset.action;
  if(action==='join'){s.student.name=document.querySelector('#student-name').value.trim().slice(0,90);s.student.form=document.querySelector('#student-form').value.trim().slice(0,35);if(C.guidedName(s.student.name)){s.guided=true;s.lang='bi';}s.joined=true;save();setHash(s.slide);render(true);}
  else if(action==='home'){s.joined=false;save();render(true);}
  else if(action==='toggle-purpose'){const rail=document.querySelector('.rail'),open=rail.classList.toggle('expanded');b.setAttribute('aria-expanded',String(open));}
  else if(action==='previous')navigate(C.previous(s));
  else if(action==='next')goNext();
  else if(action==='guided'){s.guided=!s.guided;save();if(dialog.open)closeDialog();render();}
  else if(action==='demo-tap'){s.demo.clicked=true;save();render();}
  else if(action==='demo-reset'){s.demo.clicked=false;save();render();}
  else if(action==='resources')resources();
  else if(action==='close-dialog')closeDialog();
  else if(action==='backup'){save();download(JSON.stringify(s,null,2),'My_App_Lesson_Backup.json','application/json');}
  else if(action==='import-backup')document.querySelector('#backup-file').click();
  else if(action==='pdf')report(true);
  else if(action==='read-report')report(false);
  else if(action==='new-record')showDialog(`<h3>${t('Start with a blank lesson record?','开始新的空白课程记录？')}</h3><p>${t('Download a backup first if you want to keep the current learner’s notes. The MIT project is saved separately in MIT.','若要保留当前同学的笔记，请先下载备份。MIT 项目另行保存在 MIT。')}</p><div class="button-row"><button class="button" data-action="backup">${t('Keep a backup','保留备份')}</button><button class="button primary" data-action="confirm-new">${t('Start a new record','开始新记录')}</button></div>`);
  else if(action==='confirm-new'){const lang=s.lang;s=C.initial();s.lang=lang;closeDialog();save();history.replaceState(null,'',location.pathname+location.search);render(true);}
 }
 else if(b.dataset.go)navigate(b.dataset.go);
 else if(b.dataset.guide)showGuide(b.dataset.guide);
 else if(b.dataset.help)showHelp(b.dataset.help);
 else if(b.dataset.choice){s[b.dataset.choice]=b.dataset.value;save();render();}
 else if(b.dataset.topic){C.seedTopic(s,b.dataset.topic);save();render();}
 else if(b.dataset.demoTopic){s.demo={topic:b.dataset.demoTopic,clicked:false};save();render();}
 else if(b.dataset.check){s.attempted[b.dataset.check]=true;save();render();}
 else if(b.dataset.copy)copyWord(b.dataset.copy);
 else if(b.dataset.useWord){const key=b.dataset.useWord;s.words[key]=C.topic(s)?.[key]||'';save();render();}
 else if(b.dataset.useName){s.words.title=b.dataset.useName;save();render();}
 else if(b.dataset.tutor!==undefined){s.tutor=Number(b.dataset.tutor);save();render();}
 else if(b.dataset.flag){const id=b.dataset.flag;if(!s.helpFlags.includes(id))s.helpFlags.push(id);s.work[s.slide]='help';if(id==='access')s.access='waiting';closeDialog();C.advance(s);setHash(s.slide);save();render(true);}
 else if(b.hasAttribute('data-starter-download')){s.downloaded=true;save();setTimeout(()=>render(),100);}
});
document.addEventListener('change',ev=>{const x=ev.target;if(x.id==='language'){s.lang=x.value==='bi'?'bi':'en';save();if(dialog.open)closeDialog();render();}
 else if(x.dataset.answer){s.answers[x.dataset.answer]=x.value;s.attempted[x.dataset.answer]=false;save();render();}
 else if(x.dataset.learning){s.learning[x.dataset.learning]=x.value;save();render();}
 else if(x.hasAttribute('data-access')){s.access=x.value;save();render();}
 else if(x.dataset.test){s.work[x.dataset.test]=x.type==='checkbox'?(x.checked?'done':'not-tried'):x.value;save();render();}
 else if(x.dataset.pit){s.pit[x.dataset.pit]=x.value;save();render();}
});
document.addEventListener('input',ev=>{const x=ev.target;if(x.dataset.word){if(x.dataset.word==='reset'){s.work['try-reset']='not-tried';const check=document.querySelector('.challenge-check input');if(check)check.checked=false;}if(x.dataset.word==='response')s.work['try-button']='not-tried';s.words[x.dataset.word]=x.value.slice(0,x.dataset.word==='response'?240:120);save();const prev=document.querySelector('#name-preview');if(prev)prev.textContent=s.words.title||'Your app name';document.querySelectorAll('[data-copy]').forEach(b=>b.disabled=!s.words[b.dataset.copy]?.trim());const next=document.querySelector('[data-action="next"]');if(next)next.disabled=!teacher&&!allowedNext(active());}});
document.querySelector('#backup-file').addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;try{if(file.size>1500000)throw new Error('File too large');const restored=C.restore(JSON.parse(await file.text()));s=restored;save();if(dialog.open)closeDialog();setHash(s.slide);render(true);toast('Lesson progress restored.','课程进度已恢复。');}catch(_){toast('Choose a valid backup from this MIT practical lesson.','请选择本次 MIT 实践课的有效备份。');}ev.target.value='';});
window.addEventListener('popstate',()=>{if(reportMode){reportMode=false;render();return;}const id=decodeURIComponent(location.hash.slice(1));if(s.joined&&C.canVisit(s,id,teacher)){C.visit(s,id,teacher);save();render(true);}else if(s.joined)setHash(s.slide);});
dialog.addEventListener('click',ev=>{if(ev.target===dialog)closeDialog();});
document.addEventListener('keydown',ev=>{if(dialog.open||reportMode||!s.joined||/INPUT|TEXTAREA|SELECT|BUTTON|A/.test(document.activeElement?.tagName))return;if(ev.key==='ArrowRight'&&allowedNext(active())){ev.preventDefault();goNext();}if(ev.key==='ArrowLeft'){ev.preventDefault();navigate(C.previous(s));}});
if(s.joined){let id;try{id=decodeURIComponent(location.hash.slice(1));}catch(_){id='';}if(C.canVisit(s,id,teacher))C.visit(s,id,teacher);else setHash(s.slide);}
render();
})();
